export function dateOnly(value) {
  if (typeof value !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(value) || Number.isNaN(Date.parse(value + 'T00:00:00Z')) || new Date(value + 'T00:00:00Z').toISOString().slice(0,10) !== value) throw new Error('Expected a valid YYYY-MM-DD date');
  return value;
}
export const openForOwner = (items, owner) => items.filter(item => item.status === 'open' && item.owner === owner);
export function dueBefore(items, cutoff) {
  const date = dateOnly(cutoff);
  return items.filter(item => item.status === 'open' && item.due && item.due < date);
}
export const taskLines = items => items.map(item => item.id + ' | ' + item.title + ' | ' + (item.due ?? 'unscheduled')).join('\n') || 'No tasks';

