import http from 'node:http';
import fs from 'node:fs/promises';
import {fileURLToPath} from 'node:url';
import {tickets,articles} from './data.mjs';
import {json} from './http.mjs';
export function createServer() {
  return http.createServer(async(request,response)=>{
    try {
      const url=new URL(request.url,'http://localhost');
      if(request.method==='GET' && url.pathname==='/api/context') return json(response,200,{tickets,articles,agent:{id:'demo-agent',name:'Demo agent'}});
      const file={'/':'index.html','/app.mjs':'app.mjs','/style.css':'style.css'}[url.pathname];
      if(request.method==='GET' && file) {
        const text=await fs.readFile(new URL('../public/'+file,import.meta.url));
        response.writeHead(200,{'Content-Type':file.endsWith('.css')?'text/css':file.endsWith('.mjs')?'text/javascript':'text/html; charset=utf-8'});
        return response.end(text);
      }
      json(response,404,{error:'Not found'});
    } catch(error) { console.error('request_failed',error.message); json(response,500,{error:'Request failed'}); }
  });
}
if(process.argv[1]===fileURLToPath(import.meta.url)) createServer().listen(Number(process.env.PORT || 4317),'127.0.0.1',()=>console.log('Signal Desk ready on local port '+(process.env.PORT || 4317)));

