export function validateInvoice(invoice) {
 if(!invoice || typeof invoice.id!=='string' || !Array.isArray(invoice.lines))throw new Error('Invalid invoice');
 for(const line of invoice.lines) if(!Number.isInteger(line.quantity)||line.quantity<1||!Number.isInteger(line.unitCents)||line.unitCents<0)throw new Error('Invalid line');
 return invoice;
}
export const totalCents=invoice=>invoice.lines.reduce((sum,line)=>sum+line.quantity*line.unitCents,0);

