import {initialStock} from './catalog.mjs';
export function prototype() {
 const stock=new Map(initialStock.map(item=>[item.sku,item.available]));const reservations=new Map();let sequence=0;
 return {
  reserve({tenantId,requestKey,sku,quantity}){
   if(!tenantId||!requestKey||!Number.isInteger(quantity)||quantity<1)throw new Error('Invalid request');
   const key=tenantId+':'+requestKey;const prior=reservations.get(key);
   if(prior){if(prior.sku!==sku||prior.quantity!==quantity)throw new Error('Request key conflict');return {...prior};}
   const available=stock.get(sku)??0;if(available<quantity)throw new Error('Insufficient stock');
   stock.set(sku,available-quantity);const record={id:'R'+(++sequence),tenantId,requestKey,sku,quantity,status:'confirmed'};reservations.set(key,record);return {...record};
  },
  available:sku=>stock.get(sku)??0
 };
}

