export function makeStore(initial=1){
 const stock=new Map([['MUG',initial]]);const reservations=new Map();
 return {
  async readStock(sku){return stock.get(sku)??0;},
  async writeStock(sku,value){stock.set(sku,value);},
  async findReservation(key){return reservations.get(key)??null;},
  async saveReservation(key,value){reservations.set(key,{...value});},
  snapshot(){return {stock:Object.fromEntries(stock),reservations:[...reservations.values()].map(value=>({...value}))};}
 };
}

