export function service(store){
 let nextId=0;
 return async function reserve({tenantId,key,sku,quantity}){
  const existing=await store.findReservation(key);
  if(existing){
   if(existing.sku!==sku || existing.quantity!==quantity)return {status:409,body:{error:'Key conflict'}};
   return {status:200,body:{...existing}};
  }
  const available=await store.readStock(sku);
  if(available<quantity)return {status:409,body:{error:'Insufficient stock'}};
  await store.writeStock(sku,available-quantity);
  const record={id:'R'+(++nextId),tenantId,key,sku,quantity,status:'confirmed'};
  await store.saveReservation(key,record);
  return {status:201,body:record};
 };
}

