import {sessionFor} from './sessions.mjs';
import {service} from './reserve.mjs';
export function createApi(store){
 const reserve=service(store);
 return async function request({token,body}){
  const session=sessionFor(token);if(!session)return {status:401,body:{error:'Sign in required'}};
  if(!body || typeof body.key!=='string' || !body.key || body.key.length>64 || typeof body.sku!=='string' || !Number.isInteger(body.quantity) || body.quantity<1 || body.quantity>10)return {status:400,body:{error:'Invalid request'}};
  return reserve({tenantId:session.tenantId,key:body.key,sku:body.sku,quantity:body.quantity});
 };
}

